use crate::{packet::Row,sparse::Sparse};use hec_native_ic::fp::Fp;use std::collections::BTreeMap;
type V=BTreeMap<usize,u64>;
fn product(f:&Fp,a:u64,b:u64)->u64{if a==0||b==0{0}else if a==1{b}else if b==1{a}else if a==f.p-1{f.neg(b)}else if b==f.p-1{f.neg(a)}else{f.mul(a,b)}}
fn add_scaled(f:&Fp,a:&mut V,b:&V,w:u64){if w==0{return}for(&i,&v)in b{let x=f.add(*a.get(&i).unwrap_or(&0),product(f,w,v));if x==0{a.remove(&i);}else{a.insert(i,x);}}}
// P_j = label_j(seed,target,constant) + provenance_j * (A P - b).
pub fn solve(rows:&[Row],n:usize,ell:u64)->(u64,Vec<u64>){assert!(n>=3);let f=Fp::new(ell);let mut labels=vec![None;n-1];let mut proofs=vec![V::new();n-1];assert_eq!(rows[0].coeff[0],1);assert!(rows[0].coeff[1..].iter().all(|x|*x==0));labels[0]=Some([0,0,rows[0].rhs]);proofs[0].insert(0,1);labels[1]=Some([1,0,0]);let mut solver=Sparse::new(2,ell);let mut constraints=vec![];
for(i,row)in rows.iter().enumerate().skip(1){let mut l=[0,row.coeff[n-1],f.neg(row.rhs)];let mut p=V::from([(i,1)]);let mut unknown=None;for j in 0..n-1{let w=row.coeff[j];if w==0{continue}if let Some(v)=labels[j]{for k in 0..3{l[k]=f.add(l[k],product(&f,w,v[k]));}add_scaled(&f,&mut p,&proofs[j],f.neg(w));}else{assert!(unknown.is_none(),"nontriangular relation");unknown=Some((j,w));}}
if let Some((j,w))=unknown{let iv=if w==1{1}else{f.inv(w)};labels[j]=Some(l.map(|x|product(&f,f.neg(x),iv)));for x in p.values_mut(){*x=product(&f,*x,iv)}proofs[j]=p;}else{solver.insert(&l[..2],f.neg(l[2]));constraints.push(p);}}
let k=solver.k().expect("triangular constraints must determine target");let mut proof=V::new();for(i,w)in solver.witness().into_iter().enumerate(){add_scaled(&f,&mut proof,&constraints[i],w);}let mut witness=vec![0;rows.len()];for(i,w)in proof{witness[i]=w;}let mut lhs=vec![0;n];let mut rhs=0;for(row,&w)in rows.iter().zip(&witness){if w==0{continue}for j in 0..n{lhs[j]=f.add(lhs[j],product(&f,w,row.coeff[j]));}rhs=f.add(rhs,product(&f,w,row.rhs));}let mut expected=vec![0;n];expected[n-1]=1;assert_eq!(lhs,expected);assert_eq!(rhs,k);(k,witness)}
